-- 519_batch1_curated.sql — #519 shape (a), batch 1: 51 curated rows for hidden storyless OSM pins
-- Metros: Chicago (extras), New York, Queens-Nassau, Boston.
-- Each row: the hidden pin's EXACT name and stored coordinate (places:v34 rows, read 2026-10-22); one sentence in our own
-- words; the Wikipedia article as source_url. Candidates came from the all-metro scan (loose name match to a Wikipedia
-- article, same-article twins and wrong-type matches dropped, pins the live map already serves dropped), then each was
-- hand-judged. Every name was checked for same-name pins within 2 km (CURATED_MATCH_M): rows whose story already serves
-- through a same-name Wikipedia or storied OSM pin were cut, so no row overrides an existing story.
-- REVISED 2026-10-22: the five Shea Stadium base-marker rows were removed by operator choice (the bases read as clutter,
-- not stories); 519_batch1_remove_shea.sql deletes them from the live table. Those five pins return to hidden.
--
-- RUN: the SQL editor, this whole file in its own tab. Re-runnable: a row is skipped when a same-name curated row
-- already sits within 50 m. Expect 51 rows returned on the first run, 0 on a re-run.
-- THEN (new tab): select name, category, dist_m from public.curated_category_backfill(true) order by 1;
--   expect 51 rows, every dist_m 0.
-- BACK-OUT, per metro: delete from public.curated_descriptions where note = '#519 rescue line — <metro> (2026-10-22)';

with v(name, lat, lng, description, source_url, note) as (values
  ($t$Castlewood Terrace$t$, 41.9708492::double precision, -87.6521541::double precision, $t$This block-long street of 26 single-family houses, built between 1897 and 1927, is a rare holdout in Uptown, where residents resisted the high-rises that went up all around it for decades.$t$, $t$https://en.wikipedia.org/wiki/Castlewood_Terrace$t$, $t$#519 rescue line — Chicago batch 1 (2026-10-22)$t$),
  ($t$Chicago Avenue Pumping Station$t$, 41.89717::double precision, -87.6238575::double precision, $t$Built in 1869 by William W. Boyington across Michigan Avenue from the Water Tower, this station still pumps Lake Michigan water to the city, and part of it became a theater after a 2003–04 renovation.$t$, $t$https://en.wikipedia.org/wiki/Chicago_Avenue_Pumping_Station$t$, $t$#519 rescue line — Chicago batch 1 (2026-10-22)$t$),
  ($t$Louis Pasteur Monument$t$, 41.8747891::double precision, -87.6727222::double precision, $t$Put up by Cook County Hospital in 1928, Edward H. Bennett and Léon Hermant's memorial sets a bronze bust of Pasteur on a marble shaft carved with a draped woman and two children.$t$, $t$https://en.wikipedia.org/wiki/Louis_Pasteur_Memorial$t$, $t$#519 rescue line — Chicago batch 1 (2026-10-22)$t$),
  ($t$Brooklyn War Memorial$t$, 40.6984434::double precision, -73.9906261::double precision, $t$Dedicated in 1951 to Brooklynites who served in World War II, this Cadman Plaza memorial carries Charles Keck's two high-relief figures of victory and family; the hall inside is now closed.$t$, $t$https://en.wikipedia.org/wiki/Brooklyn_War_Memorial$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Casa Belvedere, The Italian Cultural Foundation$t$, 40.6285635::double precision, -74.0880908::double precision, $t$This 1908 Italian Renaissance–style mansion on Grymes Hill, built as the Louis A. and Laura Stirn House, is now a cultural center devoted to Italian studies.$t$, $t$https://en.wikipedia.org/wiki/Casa_Belvedere$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Chelsea Waterside Park$t$, 40.7492611::double precision, -74.0074571::double precision, $t$The Erie Railroad turned this former freight yard into a park in 1906 while rebuilding its ferry terminal next door; today it is part of Hudson River Park.$t$, $t$https://en.wikipedia.org/wiki/Chelsea_Waterside_Park$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Christopher House$t$, 40.5719238::double precision, -74.1478603::double precision, $t$This stone farmhouse was a meeting place during the American Revolution, when owner Joseph Christopher sat on Richmond County's Committee of Safety; it was moved to Historic Richmond Town in 1969.$t$, $t$https://en.wikipedia.org/wiki/Christopher_House_(Staten_Island)$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Dr. Martin Luther King Jr.$t$, 40.7368958::double precision, -74.1798451::double precision, $t$One of two statues of Martin Luther King Jr. at the Essex County Government Complex, standing at its newest building, the Martin Luther King Justice Building.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_Martin_Luther_King_Jr._(Newark)$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Eagle Rock Reservation$t$, 40.810245::double precision, -74.2376907::double precision, $t$This 408-acre forest reserve on First Watchung Mountain is named for a bare rock that looks down from the ridge and marks the line between Montclair and West Orange.$t$, $t$https://en.wikipedia.org/wiki/Eagle_Rock_Reservation$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Elmhurst Park Vietnam Veterans Memorial$t$, 40.7307413::double precision, -73.8852322::double precision, $t$Queens' memorial to Vietnam War veterans took more than a decade of planning and fundraising; building began in November 2018 and it was dedicated in December 2019.$t$, $t$https://en.wikipedia.org/wiki/Queens_Vietnam_Veterans_Memorial$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Flushing Fields$t$, 40.7739323::double precision, -73.8166937::double precision, $t$Bought as open farmland in 1921 by the Memorial Field of Flushing Corporation, this park was long home to Flushing High School's teams, and its name and monument honor Flushing residents killed in World War I.$t$, $t$https://en.wikipedia.org/wiki/Flushing_Fields$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Fulton Park$t$, 40.6797884::double precision, -73.9328995::double precision, $t$Named for steamboat pioneer Robert Fulton, this Bedford-Stuyvesant park sits on land the city bought in 1904 for just over $300,000.$t$, $t$https://en.wikipedia.org/wiki/Fulton_Park_(Brooklyn)$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Gas Explosion Empty Lot$t$, 40.7997084::double precision, -73.9432569::double precision, $t$On March 12, 2014, a gas explosion leveled two apartment buildings here at 1644 and 1646 Park Avenue, killing eight people and displacing 100 families.$t$, $t$https://en.wikipedia.org/wiki/2014_East_Harlem_gas_explosion$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$General G. K. Warren$t$, 40.6730088::double precision, -73.9706461::double precision, $t$Henry Baerer's 1893 bronze of the Union general stands on granite quarried from Little Round Top at Gettysburg, where a second statue of Warren also stands; it was dedicated in 1896.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_Gouverneur_K._Warren$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Herbert Von King Park$t$, 40.6896819::double precision, -73.9466087::double precision, $t$One of Brooklyn's first parks, on land acquired in 1857, it was Tompkins Park until 1985, when it was renamed for Herbert Von King, the community organizer known as the mayor of Bedford–Stuyvesant.$t$, $t$https://en.wikipedia.org/wiki/Herbert_Von_King_Park$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Jamaica Bay Wildlife Refuge - West Pond$t$, 40.6165579::double precision, -73.8256019::double precision, $t$This path runs through the Jamaica Bay Wildlife Refuge, a National Park Service refuge of open water and salt marsh that lies entirely inside New York City, split between Brooklyn and Queens.$t$, $t$https://en.wikipedia.org/wiki/Jamaica_Bay_Wildlife_Refuge$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Joan of Arc Memorial$t$, 40.7941111::double precision, -73.9764799::double precision, $t$Anna Hyatt Huntington's 1915 bronze of Joan of Arc on horseback stands on a granite base on Riverside Drive at 93rd Street.$t$, $t$https://en.wikipedia.org/wiki/Equestrian_statue_of_Joan_of_Arc_(New_York_City)$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Kearny Riverbank Park$t$, 40.774355::double precision, -74.1532489::double precision, $t$This linear park along the Passaic River was stretched to Belleville Turnpike in 2011 on reclaimed brownfield land, and it holds the boathouse used by Kearny, Belleville and Nutley high school rowers.$t$, $t$https://en.wikipedia.org/wiki/Kearny_Riverbank_Park$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Lawrence A Wein Stadium$t$, 40.8732335::double precision, -73.9164769::double precision, $t$Columbia's 17,100-seat football stadium opened in 1984 at Manhattan's northern tip, about 200 feet from Spuyten Duyvil Creek.$t$, $t$https://en.wikipedia.org/wiki/Robert_K._Kraft_Field_at_Lawrence_A._Wien_Stadium$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Maria Hernandez Park$t$, 40.703176::double precision, -73.9238644::double precision, $t$This Bushwick park is named for Maria Hernandez, who fought to drive drug dealers off her block and was shot through her Starr Street window in August 1989.$t$, $t$https://en.wikipedia.org/wiki/Maria_Hernandez_Park$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Museum of Russian Art$t$, 40.7154287::double precision, -74.0370396::double precision, $t$Founded in 1980 through a committee that helped Soviet émigrés resettle, this museum shows Russian art, especially Soviet nonconformist work, in a Paulus Hook brownstone.$t$, $t$https://en.wikipedia.org/wiki/Museum_of_Russian_Art_(New_Jersey)$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Orange Park$t$, 40.7601163::double precision, -74.2315593::double precision, $t$Built in 1899 and opened in 1900 as part of the Essex County park system that Orange resident Frederick W. Kelsey pushed to create, it now formally bears the name of Monte Irvin.$t$, $t$https://en.wikipedia.org/wiki/Orange_Park_(New_Jersey)$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Pier 57 Rooftop Park$t$, 40.743554::double precision, -74.0108072::double precision, $t$This rooftop park sits on Pier 57, opened in 1954, whose building floats on three hollow concrete caissons sunk in the Hudson that hold its basement.$t$, $t$https://en.wikipedia.org/wiki/Pier_57$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Riverfront Park$t$, 40.7348053::double precision, -74.149955::double precision, $t$Newark is building this riverside park in phases from brownfield sites along the Passaic River, itself a Superfund site; the first phase opened in 2012.$t$, $t$https://en.wikipedia.org/wiki/Newark_Riverfront_Park$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Septuagesimo Uno$t$, 40.7786693::double precision, -73.98431::double precision, $t$At 0.04 acres this sliver of a park is one of the city's smallest; its name is Latin for seventy-first, and the city took the lot in 1969 under Mayor John Lindsay's vest-pocket park campaign.$t$, $t$https://en.wikipedia.org/wiki/Septuagesimo_Uno$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$The Brant Foundation Art Study Center$t$, 40.726068::double precision, -73.9851191::double precision, $t$Peter Brant's art foundation opened here in 2019 in a yellow-brick former Con Edison substation that had been sculptor Walter De Maria's studio; Brant bought it for $27 million after De Maria died.$t$, $t$https://en.wikipedia.org/wiki/Brant_Foundation$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Torsney/Lou Lodati Playground$t$, 40.7474321::double precision, -73.9218361::double precision, $t$Named in 1952 for George F. Torsney, a Marine veteran and Queens assemblyman who campaigned for more parks in Sunnyside, this playground sits beside the Sunnyside Yard.$t$, $t$https://en.wikipedia.org/wiki/Torsney_Playground$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Treasure House$t$, 40.5720421::double precision, -74.1471803::double precision, $t$Built around 1700 by tanner Samuel Grasset, this house takes its name from a legend that Revolutionary War–era gold coins turned up during renovations around 1860.$t$, $t$https://en.wikipedia.org/wiki/Treasure_House_(Staten_Island)$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Van Vorst Park$t$, 40.718064::double precision, -74.0471579::double precision, $t$This square was the centerpiece of Van Vorst Township, a Hudson County township that existed only from 1841 to 1851.$t$, $t$https://en.wikipedia.org/wiki/Van_Vorst_Park$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Winston Churchill Square Garden$t$, 40.7298354::double precision, -74.0023514::double precision, $t$This .05-acre garden named for Winston Churchill sits at the corner of Bleecker Street, Sixth Avenue and, fittingly, Downing Street.$t$, $t$https://en.wikipedia.org/wiki/Winston_Churchill_Square$t$, $t$#519 rescue line — New York (2026-10-22)$t$),
  ($t$Mitchel Athletic Complex$t$, 40.7245394::double precision, -73.5979::double precision, $t$Built in 1984 on the site of the decommissioned Mitchel Air Force Base, this field hosted track and soccer events at the 1998 Goodwill Games.$t$, $t$https://en.wikipedia.org/wiki/Mitchel_Athletic_Complex$t$, $t$#519 rescue line — Queens-Nassau (2026-10-22)$t$),
  ($t$Old Bethpage Village Restoration Visitor Center$t$, 40.7703088::double precision, -73.4438883::double precision, $t$The way into a living-history village of dozens of 19th-century buildings Nassau County saved from demolition, on a farm the county once planned to make its zoo; the village opened in 1970.$t$, $t$https://en.wikipedia.org/wiki/Old_Bethpage_Village_Restoration$t$, $t$#519 rescue line — Queens-Nassau (2026-10-22)$t$),
  ($t$Old Burial Hill Cemetery$t$, 40.8716162::double precision, -73.4237698::double precision, $t$In 1782 British dragoons under Colonel Benjamin Thompson built Fort Golgotha on top of Huntington's old burying ground here, tearing down the nearby Presbyterian church for its timbers.$t$, $t$https://en.wikipedia.org/wiki/Fort_Golgotha_and_the_Old_Burial_Hill_Cemetery$t$, $t$#519 rescue line — Queens-Nassau (2026-10-22)$t$),
  ($t$Udall's Cove Park$t$, 40.7786111::double precision, -73.7461111::double precision, $t$Udalls Cove is one of the last salt marshes on the North Shore near New York City, kept from development by years of local activism and home to egrets, herons and muskrats.$t$, $t$https://en.wikipedia.org/wiki/Udalls_Cove$t$, $t$#519 rescue line — Queens-Nassau (2026-10-22)$t$),
  ($t$Abagail Adams Cairn$t$, 42.233847::double precision, -70.9975406::double precision, $t$From the rocks here on Penn's Hill, Abigail Adams and her young son John Quincy watched Charlestown burn during the Battle of Bunker Hill on June 17, 1775.$t$, $t$https://en.wikipedia.org/wiki/Abigail_Adams_Cairn$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Boston State Hospital$t$, 42.2866705::double precision, -71.1003108::double precision, $t$This psychiatric hospital, closed in 1979 and since torn down, was the target of Rogers v. Okin, the class action that widened patients' right to consent; part of the grounds is now Mass Audubon's Boston Nature Center.$t$, $t$https://en.wikipedia.org/wiki/Boston_State_Hospital$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Breakheart Reservation$t$, 42.487098::double precision, -71.0329653::double precision, $t$This 652-acre reservation in Saugus and Wakefield holds hardwood forest, two freshwater lakes, a winding stretch of the Saugus River and hilltop views back to Boston.$t$, $t$https://en.wikipedia.org/wiki/Breakheart_Reservation$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Clay Pit Pond Park$t$, 42.3935262::double precision, -71.1644482::double precision, $t$Clay Pit Pond is man-made: brickmakers dug clay here from 1888 to 1926, and in 1933 Wellington Brook was turned to flood the pit.$t$, $t$https://en.wikipedia.org/wiki/Clay_Pit_Pond$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Colonel William Prescott$t$, 42.3761529::double precision, -71.0608733::double precision, $t$William Wetmore Story's statue of the Revolutionary War hero stands beside the Bunker Hill Monument in Charlestown.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_William_Prescott$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Edmund Fowle House$t$, 42.3685417::double precision, -71.1801895::double precision, $t$Built in 1772, Watertown's second-oldest surviving house was where the Massachusetts Executive Council met during the first year of the Revolutionary War.$t$, $t$https://en.wikipedia.org/wiki/Edmund_Fowle_House$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Fisher Hill Reservoir Park$t$, 42.3291119::double precision, -71.1430845::double precision, $t$This park sits on the Fisher Hill Reservoir, which with its gatehouse is a historic piece of Greater Boston's public water supply.$t$, $t$https://en.wikipedia.org/wiki/Fisher_Hill_Reservoir$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Harvard Museum of Comparative Zoology$t$, 42.3788319::double precision, -71.1156986::double precision, $t$Founded as the Agassiz Museum, Harvard's zoology museum holds some 21 million specimens, of which only several thousand are on public display at a time.$t$, $t$https://en.wikipedia.org/wiki/Museum_of_Comparative_Zoology$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Holy Cross Cemetery$t$, 42.4273941::double precision, -71.0351744::double precision, $t$Established in 1868, this Roman Catholic cemetery in Malden holds more than half a million burials on 180 acres.$t$, $t$https://en.wikipedia.org/wiki/Holy_Cross_Cemetery_(Malden,_Massachusetts)$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Isaac Sprague Memorial Tower$t$, 42.3125092::double precision, -71.2748395::double precision, $t$This 75-foot brick tower in Wellesley Hills was built in 1928 to house a clock and bell given to the town back in 1874.$t$, $t$https://en.wikipedia.org/wiki/Elm_Park_and_Isaac_Sprague_Memorial_Tower$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Jamaica Pond$t$, 42.3174881::double precision, -71.1211572::double precision, $t$A kettle lake in Olmsted's Emerald Necklace, 51 feet deep at its center, Jamaica Pond is Boston's largest body of fresh water and the source of the Muddy River.$t$, $t$https://en.wikipedia.org/wiki/Jamaica_Pond$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Longfellow House-Washington's Headquarters National Historic Site$t$, 42.3769961::double precision, -71.1263719::double precision, $t$Built in 1759 for a planter who fled at the start of the Revolution, this house was George Washington's headquarters early in the war and then Henry Wadsworth Longfellow's home for almost 50 years.$t$, $t$https://en.wikipedia.org/wiki/Longfellow_House%E2%80%93Washington's_Headquarters_National_Historic_Site$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Mary Baker Eddy Historic House$t$, 42.3317762::double precision, -71.1750421::double precision, $t$This Chestnut Hill estate at 400 Beacon Street was the last home of Mary Baker Eddy, founder of Christian Science.$t$, $t$https://en.wikipedia.org/wiki/Dupee_Estate%E2%80%93Mary_Baker_Eddy_Home$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Nahant Life Saving Station$t$, 42.4307307::double precision, -70.9338226::double precision, $t$Set up in 1900 by the U.S. Life-Saving Service and run by the Coast Guard until 1964, this is one of twelve such rescue stations left in Massachusetts.$t$, $t$https://en.wikipedia.org/wiki/Nahant_Life-Saving_Station$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Piers Park$t$, 42.3645913::double precision, -71.0371967::double precision, $t$This East Boston park was built on a condemned industrial pier, its paths laid with brick and granite from the pier's original 1870 seawalls.$t$, $t$https://en.wikipedia.org/wiki/Piers_Park$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Royall House Park$t$, 42.4123063::double precision, -71.1113999::double precision, $t$This park is beside the Isaac Royall House, a National Historic Landmark museum that keeps the only surviving slave quarters in Massachusetts.$t$, $t$https://en.wikipedia.org/wiki/Royall_House_and_Slave_Quarters$t$, $t$#519 rescue line — Boston (2026-10-22)$t$),
  ($t$Cochituate Aqueduct Trail$t$, 42.3239245::double precision, -71.2147849::double precision, $t$This path follows the Cochituate Aqueduct, which carried water to Boston from 1848 to 1951.$t$, $t$https://en.wikipedia.org/wiki/Cochituate_Aqueduct$t$, $t$#519 rescue line — Boston (2026-10-22)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
